using CondoManager.Application;
using CondoManager.Domain;
using Microsoft.EntityFrameworkCore;
namespace CondoManager.Infrastructure;
public sealed partial class MeetingService
{
 private static QuorumDto QuorumResult(MeetingQuorumCheck q)=>Read<QuorumDto>(q.ContentJson);
 private async Task<VoteDto> VoteResult(MeetingVote v,CancellationToken ct){var evidence=Read<VoteEvidence>(v.ElectorateJson);var ballots=(await db.MeetingBallots.Where(b=>b.VoteId==v.Id).OrderBy(b=>b.HeadKey).ToListAsync(ct)).Select(b=>new BallotDto(b.Id,b.HeadKey,b.PrincipalId,b.ExpressedById,b.Millesimals,b.Choice,b.Revision,b.RecordedBy,b.RecordedAt)).ToArray();var evaluation=v.ResultJson==null?votingEngine.Evaluate(evidence.Criteria,evidence.Electorate,ballots.Select(b=>new CastBallot(b.HeadKey,b.Choice)).ToArray()):Read<VotingEvaluation>(v.ResultJson);return new(v.Id,v.SessionId,v.AgendaItemId,v.RuleId,v.RuleVersion,v.QuorumCheckId,v.Status,v.OpenedAt,v.ClosedAt,v.SourceFingerprint,evidence,ballots,evaluation);}
 public async Task<DecisionsDto> Decisions(Guid condo,Guid meeting,CancellationToken ct){var m=await Find(condo,meeting,ct);var qs=(await db.MeetingQuorumChecks.Where(x=>x.MeetingId==meeting).OrderBy(x=>x.CheckedAt).ToListAsync(ct)).Select(QuorumResult).ToArray();var votes=new List<VoteDto>();foreach(var v in await db.MeetingVotes.Where(x=>x.MeetingId==meeting).OrderBy(x=>x.OpenedAt).ToListAsync(ct))votes.Add(await VoteResult(v,ct));var resolutions=(await db.MeetingResolutions.Where(x=>x.MeetingId==meeting).OrderBy(x=>x.CreatedAt).ToListAsync(ct)).Select(x=>new ResolutionDto(x.Id,x.VoteId,x.AgendaItemId,x.Version,x.PreviousResolutionId,x.CorrectionReason,x.Title,x.ResolutionText,x.Outcome,x.CreatedAt,x.FinalizedBy,x.ContentJson)).ToArray();var applications=(await db.ResolutionApplications.Where(x=>x.MeetingId==meeting).OrderBy(x=>x.CreatedAt).ToListAsync(ct)).Select(x=>new ApplicationDto(x.Id,x.ResolutionId,x.RelatedType,x.RelatedId,x.HistoricalOnly,x.CreatedAt,x.AppliedBy,x.ContentJson)).ToArray();var dispositions=(await db.MeetingAgendaDispositions.Where(x=>x.MeetingId==meeting).ToListAsync(ct)).Select(x=>new DispositionDto(x.AgendaItemId,x.Disposition,x.Reason)).ToArray();var completion=await db.MeetingCompletions.SingleOrDefaultAsync(x=>x.MeetingId==meeting,ct);return new(m.Version,qs,votes,resolutions,applications,dispositions,completion==null?null:new(completion.Id,completion.SessionId,completion.CreatedAt,completion.CompletedBy,current.Role==StudioRole.Viewer?Json(new{completion.Id,completion.SessionId,completion.CreatedAt,completion.CompletedBy,completion.Fingerprint}):completion.ContentJson),(await db.MeetingBallotRevisions.Where(b=>b.MeetingId==meeting).OrderBy(b=>b.CreatedAt).ToListAsync(ct)).Select(b=>new BallotHistoryDto(b.BallotId,b.Version,b.Choice,b.ActorId,b.CreatedAt)).ToArray());}
 public Task<DecisionsDto> CheckQuorum(Guid condo,Guid meeting,QuorumInput i,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,"QuorumChecked",null,i,async m=>{if(m.Status!=MeetingStatus.InProgress)throw new InvalidOperationException("Avviare la sessione prima della verifica.");var s=await VotingSession(meeting,i.SessionId,ct);if(s.Status!=SessionStatus.InProgress)throw new InvalidOperationException("Sessione non in corso.");var at=(i.At??DateTimeOffset.UtcNow).ToUniversalTime();var r=await ApplicableRule(condo,i.RuleId,s,VotingPurpose.Constitutive,null,at,ct);var electorate=await Electorate(m,s,at,i.Options,ct);var result=votingEngine.Evaluate(Read<VotingCriteria>(r.CriteriaJson),electorate,[]);var outcome=result.Outcome switch{VoteOutcome.Approved=>QuorumOutcome.Satisfied,VoteOutcome.Rejected=>QuorumOutcome.NotSatisfied,_=>QuorumOutcome.Undetermined};var id=Guid.NewGuid();var dto=new QuorumDto(id,s.Id,r.Id,at,outcome,electorate,result);var row=new MeetingQuorumCheck(Tenant,condo,meeting,s.Id,r.Id,electorate.SnapshotId,at,Actor,Json(dto),Hash(dto));db.Add(row); // Row UUID is supplied by Entity; store it consistently in the immutable DTO.
  db.Entry(row).Property(x=>x.Id).CurrentValue=id;
 },ct);
 public Task<DecisionsDto> OpenVote(Guid condo,Guid meeting,OpenVoteInput i,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,"VoteOpened",i.RequestId,i,async m=>{
  if(m.Status!=MeetingStatus.InProgress)throw new InvalidOperationException("Assemblea non avviata.");var s=await VotingSession(meeting,i.SessionId,ct);if(s.Status!=SessionStatus.InProgress)throw new InvalidOperationException("Sessione non in corso.");var agenda=await db.MeetingAgendaItems.SingleOrDefaultAsync(a=>a.MeetingId==meeting&&a.Id==i.AgendaItemId,ct)??throw new NotFoundException();if(await db.MeetingAgendaDispositions.AnyAsync(x=>x.MeetingId==meeting&&x.AgendaItemId==agenda.Id,ct))throw new InvalidOperationException("Punto già discusso senza voto o rinviato.");if(await db.MeetingVotes.AnyAsync(v=>v.MeetingId==meeting&&v.Status==MeetingVoteStatus.Open,ct))throw new InvalidOperationException("Chiudere la votazione già aperta.");if(await db.MeetingResolutions.AnyAsync(r=>r.MeetingId==meeting&&r.AgendaItemId==agenda.Id,ct))throw new InvalidOperationException("Punto già deliberato: rettifiche testuali esplicite o nuova assemblea, senza sostituire l'esito.");
  var at=DateTimeOffset.UtcNow;var rule=await ApplicableRule(condo,i.RuleId,s,VotingPurpose.Deliberative,agenda.Category,at,ct);var q=await db.MeetingQuorumChecks.SingleOrDefaultAsync(q=>q.Id==i.QuorumCheckId&&q.MeetingId==meeting&&q.SessionId==s.Id&&q.SnapshotId==m.CurrentSnapshotId,ct)??throw new NotFoundException();var qr=QuorumResult(q);if(qr.Outcome!=QuorumOutcome.Satisfied)throw new InvalidOperationException("Quorum costitutivo non soddisfatto.");
  var cr=await ApplicableRule(condo,q.RuleId,s,VotingPurpose.Constitutive,null,at,ct);var currentConstitutive=await Electorate(m,s,at,qr.Electorate.Options??new(qr.Electorate.Acknowledgement,qr.Electorate.Exclusions),ct);var check=votingEngine.Evaluate(Read<VotingCriteria>(cr.CriteriaJson),currentConstitutive,[]);if(check.Outcome!=VoteOutcome.Approved)throw new InvalidOperationException("Presenze o rappresentanze cambiate: il quorum costitutivo va verificato nuovamente.");
  var electorate=await Electorate(m,s,at,i.Options,ct);var evidence=new VoteEvidence(Read<VotingCriteria>(rule.CriteriaJson),electorate,await Target(condo,agenda,ct),new QuorumDto(q.Id,s.Id,q.RuleId,at,QuorumOutcome.Satisfied,currentConstitutive,check));var vote=new MeetingVote(Tenant,condo,meeting,s.Id,agenda.Id,rule.Id,rule.Version,q.Id,electorate.SnapshotId,at,Actor,Json(evidence),Hash(evidence));db.Add(vote);
 },ct);
 public Task<DecisionsDto> Ballot(Guid condo,Guid meeting,Guid vote,BallotInput i,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,"BallotRecorded",null,new{Vote=vote,Input=i},async m=>{
  var v=await db.MeetingVotes.SingleOrDefaultAsync(v=>v.Id==vote&&v.MeetingId==meeting,ct)??throw new NotFoundException();v.EnsureOpen();var right=Read<VoteEvidence>(v.ElectorateJson).Electorate.Rights.SingleOrDefault(r=>r.HeadKey==i.HeadKey&&r.IsPresent)??throw new InvalidOperationException("Testa non presente o diritto assente nella platea congelata.");MeetingBallot b;if(i.BallotId==null){if(await db.MeetingBallots.AnyAsync(b=>b.VoteId==vote&&b.HeadKey==i.HeadKey,ct))throw new InvalidOperationException("Voto già registrato: modificare esplicitamente la versione corrente.");b=new(Tenant,condo,meeting,vote,right.HeadKey,right.PrincipalId,right.ExpressedById!.Value,right.Millesimals,i.Choice,Actor);db.Add(b);}else{b=await db.MeetingBallots.SingleOrDefaultAsync(b=>b.Id==i.BallotId&&b.VoteId==vote&&b.HeadKey==i.HeadKey,ct)??throw new NotFoundException();if(b.Revision!=i.BallotRevision)throw new InvalidOperationException("Versione del voto superata.");b.Amend(i.Choice,Actor);}db.Add(new MeetingBallotRevision(Tenant,condo,meeting,b.Id,vote,b.Revision,b.Choice,Actor));
 },ct);
 public Task<DecisionsDto> CloseVote(Guid condo,Guid meeting,Guid vote,VoteCommand i,bool cancel,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,cancel?"VoteCancelled":"VoteClosed",null,new{Vote=vote,Input=i},async m=>{var v=await db.MeetingVotes.SingleOrDefaultAsync(v=>v.Id==vote&&v.MeetingId==meeting,ct)??throw new NotFoundException();if(cancel)v.Cancel();else{var dto=await VoteResult(v,ct);v.Close(Json(dto.Evaluation));}},ct);
 public Task<DecisionsDto> Resolve(Guid condo,Guid meeting,ResolutionInput i,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,"ResolutionFinalized",i.RequestId,i,async m=>{
  current.RequireAdmin();var v=await db.MeetingVotes.SingleOrDefaultAsync(v=>v.Id==i.VoteId&&v.MeetingId==meeting,ct)??throw new NotFoundException();if(v.Status is not(MeetingVoteStatus.Closed or MeetingVoteStatus.Finalized))throw new InvalidOperationException("Chiudere la votazione prima della proclamazione.");var last=await db.MeetingResolutions.Where(r=>r.VoteId==v.Id).OrderByDescending(r=>r.Version).FirstOrDefaultAsync(ct);if(last?.Id!=i.PreviousResolutionId)throw new InvalidOperationException("Indicare l'ultima delibera per una rettifica testuale tracciata.");if(last!=null&&string.IsNullOrWhiteSpace(i.CorrectionReason))throw new ArgumentException("Motivo della rettifica obbligatorio.");var vote=await VoteResult(v,ct);var resolution=new MeetingResolution(Tenant,condo,meeting,v.AgendaItemId,v.Id,i.Title,i.ResolutionText,vote.Evaluation.Outcome,Actor,(last?.Version??0)+1,last?.Id,i.CorrectionReason,Json(new{Vote=vote,Previous=last?.Id,Reason=i.CorrectionReason,Title=i.Title,Text=i.ResolutionText}),i.RequestId,Hash(i));db.Add(resolution);if(last==null)v.FinalizeVote(Actor);
 },ct);
 public Task<DecisionsDto> ApplyResolution(Guid condo,Guid meeting,Guid resolution,ApplyResolutionInput i,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,"ResolutionApplied",i.RequestId,new{Resolution=resolution,i.RequestId,i.HistoricalOnly},async m=>{
  current.RequireAdmin();var r=await db.MeetingResolutions.SingleOrDefaultAsync(r=>r.MeetingId==meeting&&r.Id==resolution,ct)??throw new NotFoundException();if(r.Outcome!=VoteOutcome.Approved)throw new InvalidOperationException("Delibera non approvata.");if(await db.MeetingResolutions.AnyAsync(x=>x.PreviousResolutionId==r.Id,ct))throw new InvalidOperationException("Usare la rettifica corrente.");var v=await db.MeetingVotes.SingleAsync(v=>v.Id==r.VoteId&&v.MeetingId==meeting,ct);var evidence=Read<VoteEvidence>(v.ElectorateJson);var frozen=evidence.Target??throw new InvalidOperationException("Nessun riferimento M06 nella platea congelata.");var agenda=await db.MeetingAgendaItems.SingleAsync(a=>a.Id==v.AgendaItemId&&a.MeetingId==meeting,ct);var target=await Target(condo,agenda,ct)??throw new NotFoundException();if(target.Id!=frozen.Id||target.Type!=frozen.Type||target.Version!=frozen.Version||target.Fingerprint!=frozen.Fingerprint)throw new InvalidOperationException("Versione o contenuto M06 diverso da quello deliberato.");if(await db.ResolutionApplications.AnyAsync(a=>a.CondominiumId==condo&&a.RelatedType==target.Type&&a.RelatedId==target.Id,ct))throw new InvalidOperationException("Oggetto già collegato a una delibera: nessuna applicazione duplicata.");var already=target.Status=="Approved";
  if(i.HistoricalOnly){if(!already&&target.Type!=MeetingReference.AccountingPeriod)throw new InvalidOperationException("Collegamento storico riservato a oggetti già approvati.");}
  else{if(already)throw new InvalidOperationException("Oggetto già approvato: scegliere il collegamento storico senza cambiare date o riferimenti originari.");if(target.Status!="Proposed")throw new InvalidOperationException("Oggetto M06 non proposto per l'approvazione.");if(target.Type==MeetingReference.Budget){if(agenda.Category!=AgendaCategory.BudgetApproval)throw new InvalidOperationException("Categoria ODG incompatibile.");var preview=await budgetService.Preview(condo,target.Id,ct);await budgetService.Approve(condo,target.Id,new(preview.Hash,"Delibera "+r.Id),ct);}else if(target.Type==MeetingReference.FinalStatement){if(agenda.Category!=AgendaCategory.FinalStatementApproval)throw new InvalidOperationException("Categoria ODG incompatibile.");var f=await db.FinalStatementRows.SingleAsync(f=>f.Id==target.Id&&f.CondominiumId==condo,ct);await finalService.ApproveFinal(condo,target.Id,new(f.SourceFingerprint,"Delibera "+r.Id),ct);}else throw new InvalidOperationException("Per l'esercizio è disponibile solo il collegamento storico, senza transizioni automatiche.");}
  db.Add(new ResolutionApplication(Tenant,condo,meeting,r.Id,target.Type,target.Id,target.Fingerprint,i.HistoricalOnly,Actor,i.RequestId,Json(new{Resolution=r.Id,Target=target,After=await Target(condo,agenda,ct)})));
 },ct);
 public Task<DecisionsDto> DisposeAgenda(Guid condo,Guid meeting,DispositionInput i,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,"AgendaDisposed",null,i,async m=>{if(!await db.MeetingAgendaItems.AnyAsync(a=>a.Id==i.AgendaItemId&&a.MeetingId==meeting,ct))throw new NotFoundException();if(await db.MeetingVotes.AnyAsync(v=>v.MeetingId==meeting&&v.AgendaItemId==i.AgendaItemId&&(v.Status==MeetingVoteStatus.Open||v.Status==MeetingVoteStatus.Closed),ct)||await db.MeetingResolutions.AnyAsync(r=>r.MeetingId==meeting&&r.AgendaItemId==i.AgendaItemId&&r.Outcome!=VoteOutcome.Undetermined,ct))throw new InvalidOperationException("Punto con votazione o delibera incompatibile.");if(await db.MeetingAgendaDispositions.AnyAsync(x=>x.MeetingId==meeting&&x.AgendaItemId==i.AgendaItemId,ct))throw new InvalidOperationException("Esito del punto già registrato.");db.Add(new MeetingAgendaDisposition(Tenant,condo,meeting,i.AgendaItemId,i.Disposition,i.Reason,Actor));},ct);
 public async Task<CompletionReview> ReviewCompletion(Guid condo,Guid meeting,Guid session,CancellationToken ct){var m=await Find(condo,meeting,ct);var completed=await db.MeetingCompletions.SingleOrDefaultAsync(c=>c.MeetingId==meeting,ct);if(completed!=null){using var doc=System.Text.Json.JsonDocument.Parse(completed.ContentJson);return Read<CompletionReview>(doc.RootElement.GetProperty("Review").GetRawText());}var d=await Decisions(condo,meeting,ct);var s=await VotingSession(meeting,session,ct);var checks=new List<CompletionCheck>();void Block(string code,string message)=>checks.Add(new(code,message,true));if(m.Status!=MeetingStatus.InProgress)Block("NotStarted","Assemblea non avviata.");if(s.Status is not(SessionStatus.InProgress or SessionStatus.Ended))Block("Session","Sessione non valida per la conclusione.");if(await db.MeetingAttendances.AnyAsync(a=>a.MeetingId==meeting&&a.CheckOutAt==null,ct))Block("Attendances","Consolidare le presenze registrando tutte le uscite.");if(d.Votes.Any(v=>(v.Status==MeetingVoteStatus.Open||v.Status==MeetingVoteStatus.Closed)))Block("Votes","Votazioni aperte o non consolidate.");var agenda=await db.MeetingAgendaItems.Where(a=>a.MeetingId==meeting).ToListAsync(ct);foreach(var a in agenda)if(!d.Resolutions.Any(r=>r.AgendaItemId==a.Id&&r.Outcome!=VoteOutcome.Undetermined)&&!d.Dispositions.Any(x=>x.AgendaItemId==a.Id))Block("Agenda","Punto non deliberato da classificare: "+a.Position);
  var quorum=d.Quorums.LastOrDefault(q=>q.SessionId==s.Id);if(quorum==null||quorum.Outcome==QuorumOutcome.Undetermined)Block("Quorum","Quorum costitutivo assente o non determinabile.");else if(quorum.Outcome==QuorumOutcome.NotSatisfied&&(d.Resolutions.Count>0||agenda.Any(a=>!d.Dispositions.Any(x=>x.AgendaItemId==a.Id&&x.Disposition==AgendaDisposition.Deferred))))Block("NoConstitution","Senza quorum soddisfatto sono ammessi soltanto punti rinviati, senza delibere.");
  var details=await Details(condo,meeting,ct);var fingerprint=Hash(new{Meeting=details,Decisions=d,Session=session,Checks=checks});return new(session,checks.Count==0,checks,fingerprint);
 }
 public Task<DecisionsDto> CompleteMeeting(Guid condo,Guid meeting,CompleteMeetingInput i,CancellationToken ct)=>DecisionMutation(condo,meeting,i.ExpectedVersion,"Completed",i.RequestId,i,async m=>{current.RequireAdmin();Guard.Text(i.Reason,2000);var review=await ReviewCompletion(condo,meeting,i.SessionId,ct);if(!review.CanComplete||review.Fingerprint!=i.Fingerprint)throw new InvalidOperationException("Checklist bloccante o modificata: ripetere la verifica.");var details=await Details(condo,meeting,ct);var d=await Decisions(condo,meeting,ct);var session=await VotingSession(meeting,i.SessionId,ct);if(session.Status==SessionStatus.InProgress)session.Transition(SessionStatus.Ended);db.Add(new MeetingCompletion(Tenant,condo,meeting,session.Id,Actor,i.RequestId,Json(new{Review=review,Meeting=details,Decisions=d,Reason=i.Reason}),review.Fingerprint));m.Complete();},ct);
}
